using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Disconnects an affiliate program from the given affiliate and immediately deactivates its referral link. Returns updated information about the disconnected affiliate program
    /// </summary>
    public Task<TdLib.TdApi.Objects.ConnectedAffiliateProgram> DisconnectAffiliateProgramAsync(AffiliateType affiliate = default, string url = default)
    {

           using var activity =  StartCallActivity("DisconnectAffiliateProgramAsync", typeof(DisconnectAffiliateProgram).FullName ?? "DisconnectAffiliateProgramAsync");

           try
           {
             return client.DisconnectAffiliateProgramAsync(affiliate, url);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
